// src/components/dashboard/SciChart3DComponent.jsx
import React, { useCallback } from 'react';
import { generateUniqueColor } from '../../utils/colors';
import { SciChartReact } from 'scichart-react';

// Import all necessary SciChart classes directly from the 'scichart' package
import {
  SciChart3DSurface,
  NumericAxis3D,
  Vector3,
  OrbitModifier3D,
  MouseWheelZoomModifier3D,
  PointLineRenderableSeries3D,
  XyzDataSeries3D
} from 'scichart';

// This is the final, definitive version using the official scichart-react wrapper.
const SciChart3DComponent = ({ comparisonData, loading }) => {

  const initChart = useCallback(async (rootElement) => {
    // 1. Explicitly activate the free Community License. This is mandatory.
    SciChart3DSurface.UseCommunityLicense();

    // 2. Use SciChart's official CDN for wasm
    SciChart3DSurface.useWasmFromCDN();

    const { sciChart3DSurface, wasmContext } = await SciChart3DSurface.create(rootElement);

    // Camera setup
    sciChart3DSurface.camera.position = new Vector3(-150, 150, -150);
    sciChart3DSurface.camera.target = new Vector3(40, 7, 0);

    // Axes
    sciChart3DSurface.xAxis = new NumericAxis3D(wasmContext, { axisTitle: "Distance (m)" });
    sciChart3DSurface.yAxis = new NumericAxis3D(wasmContext, { axisTitle: "Height (m)" });
    sciChart3DSurface.zAxis = new NumericAxis3D(wasmContext, { axisTitle: "Throw Comparison" });

    // Interaction
    sciChart3DSurface.chartModifiers.add(new OrbitModifier3D());
    sciChart3DSurface.chartModifiers.add(new MouseWheelZoomModifier3D());

    // Plot each throw
    comparisonData.forEach((throwSession, index) => {
      const lineSeries3D = new PointLineRenderableSeries3D(wasmContext);
      lineSeries3D.stroke = generateUniqueColor(throwSession.id);
      lineSeries3D.strokeThickness = 3;

      const dataSeries = new XyzDataSeries3D(wasmContext);
      throwSession.trajectory.forEach(point => {
        dataSeries.append(point.distance, point.height, index * 10);
      });

      lineSeries3D.dataSeries = dataSeries;
      sciChart3DSurface.renderableSeries.add(lineSeries3D);
    });

    return { sciChartSurface: sciChart3DSurface };
  }, [comparisonData]);

  if (loading) {
    return <div className="bg-white p-6 rounded-xl shadow-lg h-[500px] animate-pulse"></div>;
  }
  
  if (!comparisonData || comparisonData.length === 0) {
    return (
      <div className="bg-white p-6 rounded-xl shadow-lg h-[500px] flex items-center justify-center">
        <p className="text-gray-500">Select one or more throws to see the 3D comparison.</p>
      </div>
    );
  }

  return (
    <div className="bg-white p-6 rounded-xl shadow-lg mt-6 flex flex-col flex-grow h-[calc(100vh-220px)]">
      <h3 className="text-xl font-semibold mb-4 text-gray-800">
        Comparative Throw Trajectory (3D View)
      </h3>
      <div className="flex-1">
        <SciChartReact
          initChart={initChart}
          style={{ width: '100%', height: '100%' }}
        />
      </div>
    </div>
  );
};

export default SciChart3DComponent;
